return {rwnpc01={id="rwnpc01",sex="男",age=30,looks=19,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",sex="女",age=26,looks=20,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",sex="男",age=30,looks=21,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",sex="男",age=25,looks=22,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",sex="女",age=25,looks=22,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",sex="女",age=25,looks=21,showequip={},withCorpse=0},rwnpc08={id="rwnpc08",sex="女",age=25,looks=21,showequip={},withCorpse=0},rwnpc09={id="rwnpc09",sex="男",age=28,looks=19,showequip={},withCorpse=0},rwnpc10={id="rwnpc10",sex="男",age=28,looks=19,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",sex="男",age=30,looks=19,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",sex="男",age=60,looks=21,showequip={},withCorpse=0},rwnpc13={id="rwnpc13",dsc="皇帝最宠爱的小女儿，与福王平王一起长大，喜欢舞刀弄枪。",sex="女",age=20,looks=27,showequip={},withCorpse=0},rwnpc14={id="rwnpc14",dsc="她衣着显贵，是贵家之女，怀抱一只金眸玄猫，和平遥公主关系极好。",sex="女",age=19,looks=28,showequip={},withCorpse=0},rwnpc15={id="rwnpc15",dsc="他是侍奉在平遥公主身边的公公。",sex="男",age=55,looks=22,showequip={},withCorpse=0},bsnpc01={id="bsnpc01",dsc="她是天狼教的大师姐刑慧，她是魏师道诸多弟子中天赋最高的一人，据说她的练毒之术已不逊“毒师”，却也不知真假。",sex="女",age=29,looks=22,showequip={},withCorpse=0},bsnpc02={id="bsnpc02",dsc="他便是鸩羽山庄年轻一代的高手欧阳啸，鸩羽山庄庄主的唯一弟子，他年纪轻轻，武功造诣已是不凡。",sex="男",age=22,looks=24,showequip={},withCorpse=0},bsnpc03={id="bsnpc03",dsc="他就是雅布陀罗，雪山寺年轻一代的代表人物，被方丈派遣至关外。",sex="男",age=25,looks=19,showequip={},withCorpse=0},bsnpc04={id="bsnpc04",dsc="他是伏龙山的堂主何应，他为人豁达大度，交得不少江湖好友，做事老练，颇得任天南赏识。",sex="男",age=35,looks=20,showequip={},withCorpse=0},bsnpc05={id="bsnpc05",dsc="他是拜日教长老莫离，整日千金买醉，已不再过问教中事务。",sex="男",age=35,looks=20,showequip={},withCorpse=0},bsnpc06={id="bsnpc06",dsc="她便是这一代的万灵谷主丁红蝶，她身穿粉红纱裙，美艳不可方物，手脚都穿戴着金银饰器，稍一活动，金银就发出的清脆的碰撞声音，十分好听。",sex="女",age=17,looks=26,showequip={},withCorpse=0},bsnpc07={id="bsnpc07",dsc="万灵谷的护法弟子，身材魁梧，方面大耳。在教中转管招募教众，教授弟子们的入门功夫。",sex="男",age=60,looks=18,showequip={},withCorpse=0},bsnpc08={id="bsnpc08",dsc="幽冥教主的二弟子，但天赋不够而未能学成教主的独门武功。",sex="男",age=20,looks=25,showequip={},withCorpse=0},bsnpc09={id="bsnpc09",dsc="他是金牛武馆的一名教头。",sex="男",age=31,looks=18,showequip={},withCorpse=0},bsnpc10={id="bsnpc10",dsc="他是海鲸帮的一个小头目，长得十分瘦弱，似乎一吹就倒。",sex="男",age=29,looks=13,showequip={},withCorpse=0},bsnpc11={id="bsnpc11",dsc="明教五行旗的厚土旗旗主陈至。",sex="男",age=45,looks=20,showequip={},withCorpse=0},bsnpc12={id="bsnpc12",dsc="他是唐门年轻一代的高手唐雷，江湖人称【唐七手】。",sex="男",age=20,looks=18,showequip={},withCorpse=0},bsnpc13={id="bsnpc13",dsc="她是虚渺宫的弟子，不爱习武，倒喜欢四处行商，总会带回来一些新鲜好玩的玩意。",sex="女",age=24,looks=21,showequip={},withCorpse=0},bsnpc14={id="bsnpc14",dsc="她生得娇小，幼时就被训练成永夜楼的杀手，因外表柔弱，常常能杀人于无意。楼中都道她是个孤儿，但又有不少人说她本是江湖名门，父母尚在人世。",sex="女",age=27,looks=21,showequip={},withCorpse=0},bsnpc15={id="bsnpc15",dsc="她是上官林之女，财神帮帮主。她智慧绝伦，以女流之躯经营庞大的财神帮，并开始开拓海外贸易。好收集奇珍异宝，富可敌国。武功习自其父，虽身手了得，但凡事都喜欢用金钱来解决，不喜动武。",sex="女",age=23,looks=26,showequip={},withCorpse=0},bsnpc16={id="bsnpc16",dsc="他是柳人行，龙城山庄的侍从，慕容业最得意的手下，他眼如点墨，眉如远山，颔下有须，足显风流。",sex="男",age=32,looks=21,showequip={},withCorpse=0},bsnpc17={id="bsnpc17",dsc="龙千慧是问情宫中生代的绝顶高手之一。她年少成名，年轻时美貌如花，又智计百出，加上出身名门，被江湖人尊称为大小姐。",sex="女",age=36,looks=30,showequip={},withCorpse=0},bsnpc18={id="bsnpc18",dsc="他一手持玉壶，一手执墨笔，既有些轻狂意气，又带着几分洒脱不羁。他看似是个寻常书生，实则武学承袭多脉，深不可测。平日里他从不以武为傲，只称自己是个目不识丁的说书人。江湖中大多传奇话本，都出自他的手笔。",sex="男",age=38,looks=28,showequip={},withCorpse=0},bsnpc19={id="bsnpc19",dsc="祝雨同是蓬莱岛的名宿，他常年住在落英湾。他武功高强，但因为极少在江湖上走动，所以听说过他名字的人不多。",sex="男",age=35,looks=24,showequip={},withCorpse=0},bsnpc20={id="bsnpc20",dsc="沈丽娘是蓬莱岛高手，同时还与祝雨同青梅竹马，十年前结为夫妻。二人夫唱妇随伉俪情深，羡煞旁人。",sex="女",age=32,looks=27,showequip={},withCorpse=0},bsnpc21={id="bsnpc21",sex="男",age=40,looks=15,showequip={},withCorpse=0},bsnpc22={id="bsnpc22",sex="男",age=27,looks=20,showequip={},withCorpse=0},bsnpc23={id="bsnpc23",dsc="他粗眉大眼，长的有些英雄气概，在全真教第三代弟子中算得上年轻有为。",sex="男",age=25,looks=20,showequip={},withCorpse=0},bsnpc24={id="bsnpc24",dsc="这是昆仑派弟子温笑笑，整天就喜欢玩耍，不爱干正事。",sex="男",age=20,looks=23,showequip={},withCorpse=0},bsnpc25={id="bsnpc25",dsc="乃是崆峒掌门的弟子，武功不凡。",sex="男",age=22,looks=24,showequip={},withCorpse=0},bsnpc26={id="bsnpc26",dsc="莫灵儿是华山掌门莫天雄的独生女儿。",sex="女",age=22,looks=20,showequip={},withCorpse=0},bsnpc27={id="bsnpc27",dsc="峨眉“三剑”之一，清丽秀雅，姿容甚美。",sex="女",age=20,looks=25,showequip={},withCorpse=0},bsnpc28={id="bsnpc28",dsc="落月山庄的一名弟子。目若秋水，风度翩翩，笑容让人捉摸不定。",sex="男",age=20,looks=23,showequip={},withCorpse=0},bsnpc29={id="bsnpc29",dsc="官府弟子，凌云的兄长，和明宗宝、齐天关系十分要好。",sex="男",age=30,looks=20,showequip={},withCorpse=0},bsnpc30={id="bsnpc30",sex="男",age=20,looks=20,showequip={},withCorpse=0},bsnpc31={id="bsnpc31",dsc="天龙寺的一名僧人。",sex="男",age=20,looks=18,showequip={},withCorpse=0},bsnpc32={id="bsnpc32",dsc="天龙寺的一名僧人。",sex="男",age=20,looks=18,showequip={},withCorpse=0},bsnpc33={id="bsnpc33",sex="男",age=40,looks=18,showequip={},withCorpse=0}}0000000